#!/usr/bin/env bash
# CORRECTIONS (relevées par le chapitre « Le routage ») + sortie de la documentation :
#   1. app/(admin)/layout.tsx : garde SERVEUR du tableau de bord (admins et traiteurs de tickets
#      seulement, les autres → accueil) ;
#   2. session lue côté serveur par le layout racine, passée par contexte : le header n'affiche
#      plus « non connecté » une fraction de seconde (useCurrentUser) ;
#   3. proxy : /test-finder, /test-picker, /simpleEditor → 404 en production (inchangés en dev) ;
#   4. doc : lien « ← Retour au site » toujours visible dans la barre latérale ;
#   5. chapitre « Le routage » réécrit en épisode (Saison 2 · Épisode 1), corrections incluses.
# Prérequis : apply-theme-toggle.sh et apply-docs-dev-3-1-routage.sh.
# Usage (racine du repo) : bash apply-fix-routage-3-points.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/app/(admin)/layout.tsx" 2>/dev/null | grep -qF "AdminZoneLayout"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "THEME_COOKIE" "apps/web/src/app/layout.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-theme-toggle.sh"; exit 1; }
grep -qF "Fondations front" "apps/web/src/features/docs/lib/docs.navigation.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-dev-3-1-routage.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/front/routage.mdx" "apps/web/src/app/layout.tsx" "apps/web/src/features/app-shell/Header.tsx" "apps/web/src/features/app-shell/UserMenu.tsx" "apps/web/src/features/auth/SessionLoader.tsx" "apps/web/src/features/docs/components/DocsSidebar.tsx" "apps/web/src/lib/stores/useSessionStore.ts" "apps/web/src/proxy.ts")
CREATED=("apps/web/src/app/(admin)/layout.tsx" "apps/web/src/features/auth/InitialSession.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "AdminZoneLayout" "apps/web/src/app/(admin)/layout.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

