echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
fix: garde serveur du tableau de bord, session sans clignement, bancs d'essai masqués, sortie de la doc

- app/(admin)/layout.tsx : layout SERVEUR au-dessus du layout client du
  tableau de bord ; seuls les admins et les membres qui traitent des
  tickets passent, les autres retournent à l'accueil.
- Session lue par le layout racine et transmise par contexte
  (InitialSessionProvider, useCurrentUser) : header et menu s'affichent
  d'emblée connectés ou non ; le store est rempli sans nouvelle requête.
- proxy : test-finder, test-picker, simpleEditor → 404 en production.
- Doc : lien « Retour au site » permanent dans la barre latérale.
- Chapitre « Le routage » mis à jour : trois fragilités, trois corrections.

